/** Upgrades legacy documents without replacing any previously edited copy or records. */
export function upgradeContent(content) {
  if (content.schemaVersion >= 2) return content;
  const next = structuredClone(content);
  next.schemaVersion = 2;
  delete next.previewToolbar;
  next.site.logo = { src: '/assets/wise-logo.png', alt: next.site.name };
  next.events = { id: 'events', eyebrow: 'Community Updates', title: 'Recent Events', description: 'News and activities from our circular community.', emptyMessage: 'Recent events will be shared here.', items: [] };
  next.contactForm = structuredClone(contactFormDefaults);
  next.implementation.steps = next.implementation.steps.map(({ id, title }) => ({ id, title }));
  if (next.implementation.eyebrow === '7-Step Methodology') next.implementation.eyebrow = 'Our Methodology';
  next.services.emptyMessage = 'Our services will be shared here.';
  next.navigation.items = next.navigation.items.map(item => item.href === '#contact' ? { ...item, href: '#contact-form' } : item);
  if (!next.navigation.items.some(item => item.href === '#events')) next.navigation.items.push({ id: 'events', label: 'Events', href: '#events' });
  if (next.navigation.action.href === '#contact') next.navigation.action.href = '#contact-form';
  return next;
}